import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';

const projects = [
  { id: 1, cat: 'Enterprise', title: 'Enterprise Digital Transformation', desc: 'Full digital overhaul for a mid-sized enterprise, resulting in 500% growth in 18 months through strategic tech adoption and process automation.', img: 'https://images.unsplash.com/photo-1552664730-d307ca884978?w=600&h=400&fit=crop', result: '500% Growth', duration: '18 Months', tags: ['Strategy', 'Automation', 'CRM'] },
  { id: 2, cat: 'Startup', title: 'Tech Startup Scaling', desc: 'Helped a tech startup go from MVP to $10M ARR through product-led growth strategy, digital marketing, and platform optimization.', img: 'https://images.unsplash.com/photo-1460925895917-adf4e565db8d?w=600&h=400&fit=crop', result: '$10M ARR', duration: '12 Months', tags: ['Growth', 'Marketing', 'Product'] },
  { id: 3, cat: 'SaaS', title: 'SaaS Platform Development', desc: 'Built and launched a full SaaS platform from scratch, achieving 10K+ active users within the first 6 months of launch.', img: 'https://images.unsplash.com/photo-1454165804606-c3d57bc86b40?w=600&h=400&fit=crop', result: '10K+ Users', duration: '6 Months', tags: ['Development', 'SaaS', 'Launch'] },
  { id: 4, cat: 'E-Commerce', title: 'E-Commerce Platform', desc: 'Designed and implemented a high-converting e-commerce platform that generated $5M+ in revenue within the first year.', img: 'https://images.unsplash.com/photo-1506905925346-21bda4d32df4?w=600&h=400&fit=crop', result: '$5M Revenue', duration: '12 Months', tags: ['E-Commerce', 'Conversion', 'Revenue'] },
  { id: 5, cat: 'Marketing', title: 'Digital Agency Rebranding', desc: 'Complete rebranding and digital transformation for a traditional agency, resulting in 3x increase in clients and revenue.', img: 'https://images.unsplash.com/photo-1469854523086-cc02fe5d8800?w=600&h=400&fit=crop', result: '3x Revenue', duration: '9 Months', tags: ['Branding', 'Marketing', 'Growth'] },
  { id: 6, cat: 'Enterprise', title: 'Corporate CRM Implementation', desc: 'Deployed a custom CRM solution that streamlined sales processes and increased team productivity by 60%.', img: 'https://images.unsplash.com/photo-1517694712202-14dd9538aa97?w=600&h=400&fit=crop', result: '60% Productivity', duration: '4 Months', tags: ['CRM', 'Enterprise', 'Automation'] },
];

const categories = ['All', 'Enterprise', 'Startup', 'SaaS', 'E-Commerce', 'Marketing'];

const Projects = () => {
  const [projectList, setProjectList] = useState(projects);
  const [loading, setLoading] = useState(true);
  const [activeFilter, setActiveFilter] = useState('All');

  useEffect(() => {
    const fetchCaseStudies = async () => {
      try {
        const res = await fetch('/wp-json/wp/v2/case_study?_embed=1');
        if (!res.ok) throw new Error('API failed');
        const data = await res.json();
        if (Array.isArray(data) && data.length > 0) {
          setProjectList(data);
        }
      } catch (err) {
        console.warn('Falling back to static case studies', err);
      } finally {
        setLoading(false);
      }
    };

    fetchCaseStudies();
  }, []);

  const filtered = activeFilter === 'All' ? projectList : projectList.filter(p => (p._cat || p.cat) === activeFilter);

  return (
    <>
      <div style={{ background: 'linear-gradient(180deg, #1a1a1a 0%, #1a472a 100%)', padding: '6rem 0', position: 'relative' }}>
        <div style={{ position: 'absolute', top: 0, left: 0, width: '100%', height: '1px', background: 'linear-gradient(90deg, transparent, #d4af37, transparent)' }}></div>
        <div className="container-fluid px-5">
          <div style={{ textAlign: 'center' }}>
            <h1 style={{ fontFamily: 'Playfair Display, serif', fontSize: '3rem', fontWeight: 800, color: '#fff', marginBottom: '1rem' }}>Case Studies</h1>
            <p style={{ fontSize: '1.2rem', color: '#b8b8b8', maxWidth: '700px', margin: '0 auto 3rem' }}>Real results from real projects — see how strategic consulting transforms businesses</p>
            <div style={{ display: 'flex', justifyContent: 'center', gap: '2rem', flexWrap: 'wrap' }}>
              {[{ val: '500+', label: 'Projects' }, { val: '50+', label: 'Clients' }, { val: '$50M+', label: 'Revenue Generated' }, { val: '12+', label: 'Years' }].map((s) => (
                <div key={s.label} style={{ textAlign: 'center' }}>
                  <span style={{ display: 'block', fontSize: '2rem', fontWeight: 800, color: '#d4af37' }}>{s.val}</span>
                  <span style={{ display: 'block', fontSize: '0.9rem', color: '#b8b8b8' }}>{s.label}</span>
                </div>
              ))}
            </div>
          </div>
        </div>
      </div>

      <div style={{ background: '#1a1a1a', padding: '3rem 0' }}>
        <div className="container-fluid px-5">
          <div style={{ display: 'flex', justifyContent: 'center', gap: '1.5rem', flexWrap: 'wrap' }}>
            {categories.map((cat) => (
              <button
                key={cat}
                onClick={() => setActiveFilter(cat)}
                style={{
                  padding: '0.75rem 1.5rem',
                  border: '2px solid #d4af37',
                  background: activeFilter === cat ? '#d4af37' : 'transparent',
                  color: activeFilter === cat ? '#0d0d0d' : '#d4af37',
                  borderRadius: '8px',
                  fontWeight: 600,
                  cursor: 'pointer',
                  transition: 'all 0.3s',
                  fontSize: '0.95rem',
                }}
              >{cat}</button>
            ))}
          </div>
        </div>
      </div>

      <div style={{ background: '#1a1a1a', padding: '5rem 0' }}>
        <div className="container-fluid px-5">
          <div className="row g-4">
            {filtered.map((project) => (
              <div className="col-lg-4 col-md-6" key={project.id}>
                <div style={{ background: 'rgba(42,65,20,0.3)', border: '1px solid rgba(212,175,55,0.2)', borderRadius: '8px', overflow: 'hidden', height: '100%', display: 'flex', flexDirection: 'column', transition: 'all 0.4s' }}
                  onMouseEnter={e => { e.currentTarget.style.borderColor = '#d4af37'; e.currentTarget.style.transform = 'translateY(-8px)'; e.currentTarget.style.boxShadow = '0 8px 32px rgba(212,175,55,0.15)'; }}
                  onMouseLeave={e => { e.currentTarget.style.borderColor = 'rgba(212,175,55,0.2)'; e.currentTarget.style.transform = 'none'; e.currentTarget.style.boxShadow = 'none'; }}>
                  <div style={{ position: 'relative', height: '220px', overflow: 'hidden' }}>
                    <img src={project._image || project.img || 'https://images.unsplash.com/photo-1460925895917-adf4e565db8d?w=600&h=400&fit=crop'} alt={project.title?.rendered || project.title} style={{ width: '100%', height: '100%', objectFit: 'cover' }} />
                  </div>
                  <div style={{ padding: '1.5rem', flexGrow: 1, display: 'flex', flexDirection: 'column' }}>
                    <span style={{ display: 'inline-block', padding: '0.4rem 0.8rem', background: 'rgba(212,175,55,0.1)', color: '#d4af37', fontSize: '0.75rem', fontWeight: 700, textTransform: 'uppercase', borderRadius: '4px', marginBottom: '1rem', width: 'fit-content' }}>
                      {project._cat || project.cat || 'Project'}
                    </span>
                    <h3 style={{ fontFamily: 'Playfair Display, serif', fontSize: '1.3rem', color: '#fff', marginBottom: '0.75rem' }}>
                      {project.title?.rendered || project.title}
                    </h3>

                    {project.excerpt?.rendered ? (
                      <div className="wp-excerpt" style={{ color: '#b8b8b8', fontSize: '0.95rem', lineHeight: '1.6', flexGrow: 1 }} dangerouslySetInnerHTML={{ __html: project.excerpt.rendered }} />
                    ) : (
                      <p style={{ color: '#b8b8b8', fontSize: '0.95rem', lineHeight: '1.6', flexGrow: 1 }}>{project.desc}</p>
                    )}

                    <div style={{ display: 'flex', gap: '1.5rem', margin: '1rem 0', padding: '1rem 0', borderTop: '1px solid rgba(212,175,55,0.2)', borderBottom: '1px solid rgba(212,175,55,0.2)' }}>
                      <span style={{ color: '#d4af37', fontWeight: 600, fontSize: '0.85rem' }}><i className="fas fa-chart-line me-1"></i>{project._result || project.result || 'View Case Study'}</span>
                      <span style={{ color: '#d4af37', fontWeight: 600, fontSize: '0.85rem' }}><i className="fas fa-clock me-1"></i>{project._duration || project.duration || 'Ongoing'}</span>
                    </div>
                    <div style={{ display: 'flex', gap: '0.5rem', flexWrap: 'wrap', marginTop: '1rem' }}>
                      {(project._tags || project.tags || []).map(tag => (
                        <span key={tag} style={{ padding: '0.35rem 0.7rem', background: 'rgba(212,175,55,0.05)', color: '#b8b8b8', fontSize: '0.75rem', border: '1px solid rgba(212,175,55,0.15)', borderRadius: '4px' }}>{tag}</span>
                      ))}
                    </div>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>
    </>
  );
};

export default Projects;
